from collections import defaultdict
from functools import cmp_to_key

def compare(arr1, arr2):
    arr1 += [0] * (len(arr1) - len(arr2))
    arr2 += [0] * (len(arr2) - len(arr1))
    for i in range(min(len(arr1), len(arr2))):
        if arr1[i] < arr2[i]:
            return -1
        elif arr1[i] > arr2[i]:
            return 1
    return 0

def solve():
    t = int(input())
    for _ in range(t):
        n, m = map(int, input().split())
        arr = list(map(int, input().split()))
        subarrays = defaultdict(list)
        for i in range(n):
            for j in range(i + 1, n + 1):
                subarrays[j].append(arr[i:j])
        subarrays = sorted(subarrays.values(), key=cmp_to_key(compare), reverse=True)
        for _ in range(m):
            p = int(input())
            print(max(subarrays[p - 1]))

