def count_occurrences_brute_force(arr, key, from_):
    count = 0
    for i in range(from_, len(arr)):
        if arr[i] == key:
            count += 1
    return count

def count_occurrences_dp(arr, key, from_):
    dp = [0] * (len(arr) + 1)
    def count_occurrences(key, from_):
        if from_ == len(arr):
            return 0
        if dp[from_]:
            return dp[from_]
        if arr[from_] == key:
            dp[from_] = 1 + count_occurrences(key, from_ + 1)
        else:
            dp[from_] = count_occurrences(key, from_ + 1)
        return dp[from_]
    return count_occurrences(key, from_)

