def next_permutation(p):
    i = len(p) - 2
    while i >= 0 and p[i] >= p[i+1]:
        i -= 1
    if i == -1:
        return sorted(p)
    j = len(p) - 1
    while j > i and p[j] <= p[i]:
        j -= 1
    p[i], p[j] = p[j], p[i]
    p[i+1:] = p[i+1:][::-1]
