import sys
from collections import defaultdict

def read_input():
    n = int(sys.stdin.readline())
    graph = defaultdict(list)
    for i in range(1, n + 1):
        row = list(map(int, sys.stdin.readline().split()))
        for j, cost in enumerate(row):
            if i != j:
                graph[i].append((j, cost))
    return n, graph

def minimum_cost(n, graph):
    parent = list(range(n + 1))
    rank = [0] * (n + 1)
    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]
    def union(x, y):
        root_x = find(x)
        root_y = find(y)
        if root_x != root_y:
            if rank[root_x] > rank[root_y]:
                parent[root_y] = root_x
            else:
                parent[root_x] = root_y
                if rank[root_x] == rank[root_y]:
                    rank[root_y] += 1
    edges = []
    for city, neighbors in graph.items():
        for neighbor, cost in neighbors:
            edges.append((cost, city, neighbor))
    edges.sort()
    min_cost = 0
    for cost, city, neighbor in edges:
        if find(city) != find(neighbor):
            min_cost += cost
            union(city, neighbor)
    return min_cost

n, graph = read_input()
print(minimum_cost(n, graph))

