from math import comb

def solve(n, k):
    res = 0
    for i in range(1, n+1):
        if i**k > n:
            break
        cnt = Counter({i**k})
        total = i**k
        for j in range(i+1, n+1):
            if j**k > n:
                break
            if total + j**k > n:
                break
            if j**k not in cnt:
                cnt[j**k] = 0
            cnt[j**k] += 1
            total += j**k
            if total == n:
                res += comb(cnt[j**k], 1)
