def power(n, k):
    if k == 0:
        return 1
    res = power(n, k // 2)
    res = (res * res) % mod
    if k % 2:
        res = (res * n) % mod
    return res

def prime_factors(n):
    i = 2
    factors = []
    while i * i <= n:
        if n % i:
            i += 1
        else:
            n //= i
            factors.append(i)
    if n > 1:
        factors.append(n)
    return factors

def sum_of_numbers(n, primes, powers, min_powers):
    sum = 0
    for i in range(n + 1):
        for j in range(len(primes)):
            if powers[j] < min_powers[j]:
                break
            i //= power(primes[j], powers[j])
            sum += i
            sum %= mod
    return sum

