def power(x, y):
    res = 1
    while y > 0:
        if y % 2 == 1:
            res = res * x
        y = y // 2
        x = x * x
    return res

def order(arr, i):
    if len(arr) <= 1:
        return arr
    l = []
    r = []
    n = len(arr) - 1
    for j in range(n + 1):
        if (arr[j] % power(2, i + 1)) < power(2, i):
            l.append(arr[j])
        else:
            r.append(arr[j])
    l = order(l, i + 1)
    r = order(r, i + 1)
    return l + r

