def min_remove_to_make_k_good(word, k):
    freq = defaultdict(int)
    for char in word:
        freq[char] += 1
    min_diff = float('inf')
    for char in freq:
        diff = abs(freq[char] - sum(freq.values()) // len(freq))
        min_diff = min(min_diff, diff)
    return max(0, k - min_diff)

