from collections import deque

def bfs(graph, start, end, path, visited):
    queue = deque([(start, path)])
    while queue:
        vertex, path = queue.popleft()
        if vertex == end:
            return path
        for neighbor in graph[vertex]:
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, path + str(neighbor)))

def is_realizable(graph, s):
    vertex_map = {'A': 0, 'B': 1, 'C': 2, 'D': 3, 'E': 4}
    for vertex in range(10):
        visited = set()
        path = bfs(graph, vertex, vertex, str(vertex), visited)
        i = 0
        while i < len(s):
            if path[i] in vertex_map and vertex_map[path[i]] == vertex_map[s[i]]:
                i += 1
            if i == len(s):
                return path
            path = bfs(graph, vertex, vertex_map[s[i]], path + str(vertex_map[s[i]]), visited)
    return -1

